            ['start_time' => 2255.48, 'end_time' => 2257.86, 'target_text' => 'You You\'re not dressing appropriately, Allah knows your heart.', 'source_text' => 'Anda berpakaian mendedahkan aurat, \'Allah tahu isi hati saya\'.', 'order' => 712],
            ['start_time' => 2257.96, 'end_time' => 2260.46, 'target_text' => 'You\'re sending the alcohol, Allah knows your heart.', 'source_text' => 'Anda mengedar minuman arak, \'Allah tahu isi hati saya\'.', 'order' => 713],
            ['start_time' => 2260.56, 'end_time' => 2262.34, 'target_text' => 'You\'re doing everything else, Allah knows your heart.', 'source_text' => 'Anda melakukan pelbagai lagi kemungkaran, lalu beralasan \'Allah tahu isi hati saya\'.', 'order' => 714],
            ['start_time' => 2262.44, 'end_time' => 2263.86, 'target_text' => 'What\'s the point of Islam?', 'source_text' => 'Maka apakah gunanya kita berpegang kepada ajaran Islam?', 'order' => 715],
            ['start_time' => 2263.96, 'end_time' => 2266.66, 'target_text' => 'Allah knows the heart, everybody\'s heart.', 'source_text' => 'Allah Maha Mengetahui setiap isi hati, isi hati setiap hamba-Nya.', 'order' => 716],
            ['start_time' => 2266.76, 'end_time' => 2272.02, 'target_text' => 'That\'s why I say, "Don\'t be deceived by the statement of shaytan." What does he tell you?', 'source_text' => 'Sebab itulah saya tegaskan, "Jangan sesekali terpedaya dengan bisikan helah Syaitan." Apakah yang cuba diputarbelitkannya?', 'order' => 717],
            ['start_time' => 2272.12, 'end_time' => 2277.42, 'target_text' => 'He tells you, "Walakin yanzuru ila qulubikum wa a\'malikum." Hadith is correct.', 'source_text' => 'Dia membacakan potongan hadis, "Walakin yanzuru ila qulubikum wa a\'malikum." Hadis tersebut memang sahih.', 'order' => 718],
            ['start_time' => 2277.52, 'end_time' => 2279.82, 'target_text' => 'Allah looks at your hearts and your your deeds.', 'source_text' => 'Sesungguhnya Allah memandang kepada hati-hati kamu dan amalan-amalan perbuatan kamu.', 'order' => 719],
            ['start_time' => 2279.92, 'end_time' => 2283.22, 'target_text' => 'Notice how both of those go hand in hand.', 'source_text' => 'Perhatikan bagaimana kedua-dua unsur itu saling bergandingan dan tidak boleh dipisahkan sama sekali.', 'order' => 720],
            ['start_time' => 2283.32, 'end_time' => 2285.94, 'target_text' => 'Don\'t only say one without the other.', 'source_text' => 'Jangan hanya mengambil satu aspek dan meninggalkan aspek yang satu lagi.', 'order' => 721],
            ['start_time' => 2286.04, 'end_time' => 2291.9, 'target_text' => 'Don\'t only say heart without deeds because that hadith did not only mention the heart and did not only mention the deeds.', 'source_text' => 'Jangan hanya berhujah dengan \'hati\' tanpa \'amalan perbuatan\', kerana hadis tersebut tidak menyebut tentang hati sahaja, dan tidak pula menyebut tentang amalan semata-mata.', 'order' => 722],
            ['start_time' => 2292.0, 'end_time' => 2293.46, 'target_text' => 'It mentioned both of them.', 'source_text' => 'Hadis itu menyebut kedua-duanya sekali gus.', 'order' => 723],
            ['start_time' => 2293.56, 'end_time' => 2301.14, 'target_text' => 'And from that, some of the muhaddithin have explained that Allah looks at your heart and your deed to see the intention of', 'source_text' => 'Dan daripada hadis itulah para muhaddisin (ulama hadis) menghuraikan bahawa Allah memandang kepada hatimu dan amalanmu demi menilai keikhlasan niat di sebalik', 'order' => 724],
            ['start_time' => 2301.24, 'end_time' => 2301.98, 'target_text' => 'the deed.', 'source_text' => 'amalan tersebut.', 'order' => 725],
            ['start_time' => 2302.08, 'end_time' => 2305.16, 'target_text' => 'and if the deed is wrong', 'source_text' => 'Dan sekiranya amalan perbuatannya salah,', 'order' => 726],
            ['start_time' => 2306.56, 'end_time' => 2311.14, 'target_text' => 'and the heart is wrong in the wrong place, you\'ve lost completely.', 'source_text' => 'serta niat di dalam hatinya juga terpesong, sesungguhnya kamu telah rugi sepenuhnya.', 'order' => 727],
            ['start_time' => 2311.24, 'end_time' => 2313.06, 'target_text' => 'But Allah looks at both.', 'source_text' => 'Namun Allah memandang kepada kedua-duanya.', 'order' => 728],
            ['start_time' => 2313.16, 'end_time' => 2316.9, 'target_text' => 'You need to do your salah and Allah will help you and guide you.', 'source_text' => 'Anda wajib menunaikan solat fardu anda dan Allah pasti akan memimpin serta membantu anda.', 'order' => 729],
            ['start_time' => 2317.0, 'end_time' => 2322.22, 'target_text' => 'If I see someone fulfilling salah in the masjid and I walked in, I can\'t say, "Look at this guy.', 'source_text' => 'Sekiranya saya melihat seseorang sedang khusyuk menunaikan solat di masjid ketika saya melangkah masuk, saya tidak berhak berkata, "Tengok orang itu,', 'order' => 730],
            ['start_time' => 2322.32, 'end_time' => 2325.3, 'target_text' => 'He\'s he\'s showing off." How do I know he\'s showing off?', 'source_text' => 'dia sedang menunjuk-nunjuk (riya\')." Bagaimana mungkin saya tahu bahawa dia menunjuk-nunjuk?', 'order' => 731],
            ['start_time' => 2325.4, 'end_time' => 2326.34, 'target_text' => 'It\'s a deed.', 'source_text' => 'Itu amalan ibadahnya.', 'order' => 732],
            ['start_time' => 2326.44, 'end_time' => 2327.54, 'target_text' => 'Allah knows his heart.', 'source_text' => 'Hanya Allah yang mengetahui apa yang tersembunyi di dalam hatinya.', 'order' => 733],
            ['start_time' => 2327.64, 'end_time' => 2330.46, 'target_text' => 'In that instance, it\'s correct to say Allah knows the man\'s heart.', 'source_text' => 'Dalam konteks sebeginilah amat tepat untuk diucapkan bahawa hanya Allah yang mengetahui isi hati seseorang hamba.', 'order' => 734],
            ['start_time' => 2330.56, 'end_time' => 2332.3, 'target_text' => 'Leave him alone.', 'source_text' => 'Biarkan urusan hatinya antara dirinya dengan Allah.', 'order' => 735],
            ['start_time' => 2332.4, 'end_time' => 2334.42, 'target_text' => 'But don\'t ever use it to justify.', 'source_text' => 'Tetapi jangan sesekali menggunakannya sebagai alasan untuk menghalalkan kemungkaran diri.', 'order' => 736],
            ['start_time' => 2334.52, 'end_time' => 2336.42, 'target_text' => 'I want to teach you something, my beloved children.', 'source_text' => 'Saya ingin mengajar sesuatu kepada anda, wahai anak-anakku yang dikasihi.', 'order' => 737],
            ['start_time' => 2336.52, 'end_time' => 2339.02, 'target_text' => 'When someone corrects you, you must say, "Jazakallahu khairan.', 'source_text' => 'Apabila seseorang menegur kesilapan anda, wajarlah anda membalas, "Jazakallahu khairan.', 'order' => 738],
            ['start_time' => 2339.12, 'end_time' => 2342.54, 'target_text' => 'Thank you very much." With me, someone corrects me up to now.', 'source_text' => 'Terima kasih banyak-banyak." Begitu juga halnya dengan diri saya apabila ada orang menegur saya sehingga ke hari ini.', 'order' => 739],
            ['start_time' => 2342.64, 'end_time' => 2346.42, 'target_text' => 'They say, "This guy I\'m sure you might have heard they say he doesn\'t talk about Gaza.', 'source_text' => 'Ada orang menuduh, "Orang ini — saya yakin anda mungkin pernah mendengarnya — dia tidak bercakap tentang isu Gaza.', 'order' => 740],
            ['start_time' => 2346.52, 'end_time' => 2347.22, 'target_text' => 'He doesn\'t do this.', 'source_text' => 'Dia tidak memperjuangkan isu ini.', 'order' => 741],
            ['start_time' => 2347.32, 'end_time' => 2348.94, 'target_text' => 'He\'s a Zionist." What do you know what?', 'source_text' => 'Dia ini seorang penyokong Zionis." Tahukah anda apa sikap saya?', 'order' => 742],
            ['start_time' => 2349.04, 'end_time' => 2349.74, 'target_text' => 'That\'s their opinion.', 'source_text' => 'Itu pandangan peribadi mereka.', 'order' => 743],
            ['start_time' => 2349.84, 'end_time' => 2350.86, 'target_text' => 'They probably don\'t know.', 'source_text' => 'Mereka berkemungkinan besar tidak mengetahui hakikat sebenar.', 'order' => 744],
            ['start_time' => 2350.96, 'end_time' => 2354.58, 'target_text' => 'They are probably victim of the algorithms and they don\'t even know.', 'source_text' => 'Mereka mungkin menjadi mangsa sekatan algoritma media sosial tanpa mereka sendiri menyedarinya.', 'order' => 745],
            ['start_time' => 2354.68, 'end_time' => 2360.7, 'target_text' => 'But I don\'t want to cause a war with my own brothers and sisters because they are thinking bad of me.', 'source_text' => 'Namun saya tidak mahu mencetuskan perbalahan sesama saudara seislam saya semata-mata kerana mereka bersangka buruk terhadap saya.', 'order' => 746],
            ['start_time' => 2360.8, 'end_time' => 2366.54, 'target_text' => 'I\'d rather they think bad of me and the ummah remains together than for me to fight them and split the ummah in another 20', 'source_text' => 'Saya lebih rela mereka bersangka buruk terhadap peribadi saya asalkan kesatuan ummah kekal terpelihara, daripada saya membalas serangan mereka lalu memecahbelahkan ummah kepada 20', 'order' => 747],
            ['start_time' => 2366.64, 'end_time' => 2367.66, 'target_text' => 'different ways.', 'source_text' => 'puak yang berbeza.', 'order' => 748],
            ['start_time' => 2367.76, 'end_time' => 2369.14, 'target_text' => 'We are not Zionistic.', 'source_text' => 'Kita sama sekali bukan penyokong Zionis.', 'order' => 749],
            ['start_time' => 2369.24, 'end_time' => 2376.78, 'target_text' => 'We are definitely pro-Palestine and pro-Gaza and we\'ve done more than we have pro more than we have advertised.', 'source_text' => 'Kita berdiri teguh menyokong perjuangan Palestin dan membela warga Gaza, malah kami telah menyalurkan bantuan jauh lebih banyak daripada apa yang kami war-warkan kepada umum.', 'order' => 750],
            ['start_time' => 2376.88, 'end_time' => 2382.86, 'target_text' => 'And we will definitely continue to speak about the genocide that continues up to now.', 'source_text' => 'Dan kami akan terus-menerus bersuara menentang kekejaman pembunuhan beramai-ramai (genosid) yang masih berlarutan sehingga ke saat ini.', 'order' => 751],
            ['start_time' => 2382.96, 'end_time' => 2384.54, 'target_text' => 'Even though they say there is a ceasefire.', 'source_text' => 'Walaupun ada pihak yang mendakwa kononnya telah berlaku gencatan senjata.', 'order' => 752],
            ['start_time' => 2384.64, 'end_time' => 2385.46, 'target_text' => 'What ceasefire?', 'source_text' => 'Gencatan senjata apa yang dimaksudkan?', 'order' => 753],
            ['start_time' => 2385.56, 'end_time' => 2387.7, 'target_text' => 'Every day they are dying.', 'source_text' => 'Setiap hari saudara kita di sana terus gugur syahid.', 'order' => 754],
            ['start_time' => 2387.8, 'end_time' => 2389.94, 'target_text' => 'Not just dying, being butchered and murdered.', 'source_text' => 'Bukan sekadar meninggal dunia biasa, mereka disembelih, dibantai dan dibunuh dengan kejam.', 'order' => 755],
            ['start_time' => 2390.04, 'end_time' => 2391.5, 'target_text' => 'And every day land is being taken.', 'source_text' => 'Dan setiap hari tanah air mereka terus dirampas.', 'order' => 756],
            ['start_time' => 2391.6, 'end_time' => 2393.1, 'target_text' => 'Do you know?', 'source_text' => 'Tahukah anda?', 'order' => 757],
            ['start_time' => 2393.2, 'end_time' => 2395.94, 'target_text' => 'I came in here and I wanted to say to you, "Do you know what?', 'source_text' => 'Saya melangkah masuk ke sini dan saya ingin menegaskan kepada anda, "Tahukah anda?', 'order' => 758],
            ['start_time' => 2396.04, 'end_time' => 2400.98, 'target_text' => 'Our brothers and sisters are all over I am very very on the button with what\'s going on.', 'source_text' => 'Saudara-mara kita berada di seluruh pelosok dunia, dan saya sentiasa mengikuti rapat setiap perkembangan terkini yang berlaku.', 'order' => 759],
            ['start_time' => 2401.08, 'end_time' => 2401.78, 'target_text' => 'Trust me.', 'source_text' => 'Percayalah kepada saya.', 'order' => 760],
            ['start_time' => 2401.88, 'end_time' => 2407.78, 'target_text' => 'I will tell you what happened today in Nepal, what happened yesterday in Indonesia and the last 2 weeks in the Philippines', 'source_text' => 'Saya boleh memberitahu anda apa yang berlaku pada hari ini di Nepal, apa yang menimpa semalam di Indonesia, dan apa yang melanda Filipina dalam tempoh dua minggu lalu,', 'order' => 761],
            ['start_time' => 2407.88, 'end_time' => 2409.22, 'target_text' => 'and those kind I will let you know.', 'source_text' => 'dan musibah seumpamanya, saya akan kongsikan dengan anda.', 'order' => 762],
            ['start_time' => 2409.32, 'end_time' => 2410.14, 'target_text' => 'There were earthquakes.', 'source_text' => 'Berlaku bencana gempa bumi.', 'order' => 763],
            ['start_time' => 2410.24, 'end_time' => 2411.02, 'target_text' => 'There were mudslides.', 'source_text' => 'Berlaku tragedi tanah runtuh.', 'order' => 764],
            ['start_time' => 2411.12, 'end_time' => 2411.86, 'target_text' => 'There were tsunamis.', 'source_text' => 'Berlaku malapetaka tsunami.', 'order' => 765],
            ['start_time' => 2411.96, 'end_time' => 2415.94, 'target_text' => 'There were so much more there and so much of destruction and floods.', 'source_text' => 'Terlalu banyak kemusnahan harta benda dan banjir besar yang melanda di sana.', 'order' => 766],
            ['start_time' => 2416.04, 'end_time' => 2419.7, 'target_text' => 'Do you even know this?" So, it\'s all over the world.', 'source_text' => 'Pernahkah anda mengambil tahu tentang semua ini?" Musibah berlaku di seluruh pelusuk dunia.', 'order' => 767],
            ['start_time' => 2419.8, 'end_time' => 2421.02, 'target_text' => 'I belong to a charity.', 'source_text' => 'Saya bernaung di bawah sebuah badan kebajikan.', 'order' => 768],
            ['start_time' => 2421.12, 'end_time' => 2424.46, 'target_text' => 'I work with an international aid organization.', 'source_text' => 'Saya berkhidmat bersama sebuah organisasi bantuan kemanusiaan antarabangsa.', 'order' => 769],
            ['start_time' => 2424.56, 'end_time' => 2426.66, 'target_text' => 'You really reckon I don\'t know?', 'source_text' => 'Adakah anda benar-benar menyangka bahawa saya tidak mengambil peduli?', 'order' => 770],
            ['start_time' => 2426.76, 'end_time' => 2429.42, 'target_text' => 'If you didn\'t see something, who does that platform belong to?', 'source_text' => 'Sekiranya anda tidak melihat sesuatu hantaran di media sosial, milik siapakah platform tersebut?', 'order' => 771],
            ['start_time' => 2429.52, 'end_time' => 2430.54, 'target_text' => 'Why didn\'t you see it?', 'source_text' => 'Mengapa anda tidak dapat melihatnya?', 'order' => 772],
            ['start_time' => 2430.64, 'end_time' => 2431.54, 'target_text' => 'Do you know?', 'source_text' => 'Tahukah anda puncanya?', 'order' => 773],
            ['start_time' => 2431.64, 'end_time' => 2437.1, 'target_text' => 'There\'s something called shadow banning, there\'s something called a deletion, there\'s something called There are so many things.', 'source_text' => 'Ada sistem yang dipanggil \'shadow banning\' (sekatan halimunan), ada sistem pemadaman kandungan, ada pelbagai bentuk sekatan lain.', 'order' => 774],
            ['start_time' => 2437.2, 'end_time' => 2438.82, 'target_text' => 'It doesn\'t belong to you and I.', 'source_text' => 'Platform media sosial tersebut bukan milik anda dan saya.', 'order' => 775],
            ['start_time' => 2438.92, 'end_time' => 2440.54, 'target_text' => 'Anyway, I don\'t want to get into that topic.', 'source_text' => 'Apapun, saya tidak berniat untuk memanjangkan perbahasan mengenai isu itu.', 'order' => 776],
            ['start_time' => 2440.64, 'end_time' => 2444.94, 'target_text' => 'All I\'m saying is still when people tell me something, I just say jazakallahu khairan.', 'source_text' => 'Apa yang ingin saya tegaskan adalah, apabila orang menegur saya tentang sesuatu perkara, saya tetap memilih untuk membalas, "Jazakallahu khairan.', 'order' => 777],
            ['start_time' => 2445.04, 'end_time' => 2446.5, 'target_text' => 'Uncle, please make dua for me.', 'source_text' => 'Pakcik, tolong doakan saya.', 'order' => 778],
            ['start_time' => 2446.6, 'end_time' => 2447.42, 'target_text' => 'I\'m weak.', 'source_text' => 'Saya insan yang serba lemah."', 'order' => 779],
            ['start_time' => 2447.52, 'end_time' => 2448.26, 'target_text' => 'That\'s all.', 'source_text' => 'Cukup sekadar itu.', 'order' => 780],
            ['start_time' => 2448.36, 'end_time' => 2449.74, 'target_text' => 'And end it and go away.', 'source_text' => 'Selesaikan perbualan dan beredarlah dengan tenang.', 'order' => 781],
            ['start_time' => 2449.84, 'end_time' => 2450.98, 'target_text' => 'I\'m weak.', 'source_text' => '"Saya seorang yang lemah."', 'order' => 782],
            ['start_time' => 2451.08, 'end_time' => 2453.34, 'target_text' => 'That\'s the best way of closing the discussion.', 'source_text' => 'Itulah cara yang paling damai untuk menutup sebarang pertikaian.', 'order' => 783],
            ['start_time' => 2453.44, 'end_time' => 2454.34, 'target_text' => 'Someone says, "You know what?', 'source_text' => 'Apabila seseorang berkata, "Tahukah kamu?', 'order' => 784],
            ['start_time' => 2454.44, 'end_time' => 2454.94, 'target_text' => 'You didn\'t do this.', 'source_text' => 'Kamu tidak buat perkara ini.', 'order' => 785],
            ['start_time' => 2455.04, 'end_time' => 2460.38, 'target_text' => 'You didn\'t do that." The other day in one of the masajid, I asked the people, I said, "Please give me one piece of advice."', 'source_text' => 'Kamu terlepas pandang perkara itu." Baru-baru ini di salah sebuah masjid, saya meminta jemaah dengan berkata, "Tolong berikan saya satu nasihat."', 'order' => 786],
            ['start_time' => 2460.48, 'end_time' => 2462.38, 'target_text' => 'So, many people put up their hands.', 'source_text' => 'Lalu ramai jemaah mengangkat tangan mereka.', 'order' => 787],
            ['start_time' => 2462.48, 'end_time' => 2464.98, 'target_text' => 'And one of the brothers gave me good a very good piece of advice.', 'source_text' => 'Dan salah seorang jemaah lelaki telah memberikan nasihat yang sangat bermakna kepada saya.', 'order' => 788],
            ['start_time' => 2465.08, 'end_time' => 2466.14, 'target_text' => 'And I told him jazakallahu khairan.', 'source_text' => 'Dan saya berkata kepadanya, "Jazakallahu khairan.', 'order' => 789],
            ['start_time' => 2466.24, 'end_time' => 2466.86, 'target_text' => 'Thank you so much.', 'source_text' => 'Terima kasih banyak-banyak."', 'order' => 790],
            ['start_time' => 2466.96, 'end_time' => 2469.74, 'target_text' => 'Wallahi, it was It touched my heart what he said.', 'source_text' => 'Wallahi, kata-kata nasihatnya itu benar-benar menyentuh hati sanubari saya.', 'order' => 791],
            ['start_time' => 2469.84, 'end_time' => 2472.1, 'target_text' => 'But, I was willing to listen to anything.', 'source_text' => 'Dan saya sentiasa bersedia untuk mendengar apa jua teguran.', 'order' => 792],
            ['start_time' => 2472.2, 'end_time' => 2478.14, 'target_text' => 'Imagine if I were to ask you, "Give me a piece of advice." Many of you are itching to tell me something to correct me.', 'source_text' => 'Bayangkan sekiranya saya bertanya kepada anda, "Berikan saya satu teguran." Ramai antara anda pasti berkobar-kobar ingin menegur sesuatu kesilapan saya.', 'order' => 793],
            ['start_time' => 2478.24, 'end_time' => 2480.22, 'target_text' => 'Maybe you might have heard something, seen something.', 'source_text' => 'Mungkin anda pernah mendengar sesuatu khabar angin atau melihat sesuatu perkara.', 'order' => 794],
            ['start_time' => 2480.32, 'end_time' => 2482.02, 'target_text' => 'Wallahi, I\'m willing to listen to you.', 'source_text' => 'Wallahi, saya sentiasa berlapang dada untuk mendengar pandangan anda.', 'order' => 795],
            ['start_time' => 2482.12, 'end_time' => 2489.08, 'target_text' => 'And I want to be corrected because I believe the only way we can outshine the whole world is when we accept correction.', 'source_text' => 'Dan saya bersedia untuk diperbetulkan kerana saya yakin satu-satunya jalan untuk kita melakar kecemerlangan di dunia adalah apabila kita bersedia menerima teguran.', 'order' => 796],
            ['start_time' => 2489.48, 'end_time' => 2491.06, 'target_text' => 'Otherwise, you\'re not going to move anywhere.', 'source_text' => 'Jika tidak, anda tidak akan mampu melangkah maju ke mana-mana.', 'order' => 797],
            ['start_time' => 2491.16, 'end_time' => 2493.42, 'target_text' => 'When I read Quran, I thought I knew it all.', 'source_text' => 'Dahulu ketika saya mula-mula membaca al-Quran, saya menyangka saya sudah mengetahui segalanya.', 'order' => 798],
            ['start_time' => 2493.52, 'end_time' => 2496.62, 'target_text' => 'I went to another teacher, and he corrected what I already knew.', 'source_text' => 'Lalu saya berguru dengan seorang guru lain, dan beliau memperbetulkan apa yang saya sangka saya sudah mahir.', 'order' => 799],
            ['start_time' => 2496.72, 'end_time' => 2500.34, 'target_text' => 'And then I went to a third teacher, and he corrected what I learned from the second teacher.', 'source_text' => 'Kemudian saya berguru pula dengan guru ketiga, dan beliau memperbetulkan lagi bacaan yang saya pelajari daripada guru kedua.', 'order' => 800],
            ['start_time' => 2500.44, 'end_time' => 2501.7, 'target_text' => 'And then I got ijaza.', 'source_text' => 'Dan selepas itu saya memperoleh sanad ijazah al-Quran.', 'order' => 801],
            ['start_time' => 2501.8, 'end_time' => 2504.54, 'target_text' => 'And then I made sure that ijaza was on a very high level.', 'source_text' => 'Dan saya memastikan bahawa sanad ijazah tersebut adalah pada sanad yang bersambung tinggi.', 'order' => 802],
            ['start_time' => 2504.64, 'end_time' => 2505.26, 'target_text' => 'And what happened?', 'source_text' => 'Dan apakah yang berlaku selepas itu?', 'order' => 803],
            ['start_time' => 2505.36, 'end_time' => 2508.86, 'target_text' => 'We now learned something that we really didn\'t imagine.', 'source_text' => 'Kami kini mempelajari sesuatu ilmu yang tidak pernah kami bayangkan sebelum ini.', 'order' => 804],
            ['start_time' => 2508.96, 'end_time' => 2511.06, 'target_text' => 'And when we were young, we wouldn\'t have believed.', 'source_text' => 'Dan ketika kami masih muda dahulu, kami mungkin sukar mempercayainya.', 'order' => 805],
            ['start_time' => 2511.16, 'end_time' => 2513.62, 'target_text' => 'Why did I not, you know, I\'m reading Quran.', 'source_text' => 'Mengapa dahulu saya tidak — anda tahu, ketika saya mendengar bacaan al-Quran.', 'order' => 806],
            ['start_time' => 2513.72, 'end_time' => 2515.7, 'target_text' => 'Sometimes we hear people read Quran.', 'source_text' => 'Kadangkala kita mendengar orang membaca al-Quran di sekeliling kita.', 'order' => 807],
            ['start_time' => 2515.8, 'end_time' => 2516.5, 'target_text' => 'And you know what?', 'source_text' => 'Dan tahukah anda apa yang terlintas dalam fikiran saya?', 'order' => 808],
            ['start_time' => 2516.6, 'end_time' => 2518.7, 'target_text' => 'In my mind, I say this person needs correction.', 'source_text' => 'Di dalam hati saya berbisik bahawa bacaan insan ini memerlukan pembetulan makhraj dan tajwid.', 'order' => 809],
            ['start_time' => 2518.8, 'end_time' => 2520.54, 'target_text' => 'Someone with love needs to go to them.', 'source_text' => 'Seseorang perlu mendekatinya dengan penuh kasih sayang dan kelembutan.', 'order' => 810],
            ['start_time' => 2520.64, 'end_time' => 2526.1, 'target_text' => 'Beautiful voice, beautiful tone, beautiful tune, but no tajweed, no pronunciation.', 'source_text' => 'Suaranya sungguh merdu, alunannya indah, lagunya memukau, namun tiada kaedah tajwid dan sebutan makhraj huruf yang betul.', 'order' => 811],
            ['start_time' => 2526.2, 'end_time' => 2528.48, 'target_text' => 'How would you know?', 'source_text' => 'Bagaimanakah anda boleh mengetahuinya?', 'order' => 812],
            ['start_time' => 2530.0, 'end_time' => 2531.8, 'target_text' => 'Cool.', 'source_text' => 'Hebat bukan?', 'order' => 813],
            ['start_time' => 2532.12, 'end_time' => 2534.32, 'target_text' => 'What does that mean?', 'source_text' => 'Apakah maksud di sebalik hakikat itu?', 'order' => 814],
            ['start_time' => 2534.8, 'end_time' => 2540.06, 'target_text' => 'Indeed, the people of a certain virtue are only recognized by people of a similar virtue.', 'source_text' => 'Sesungguhnya kelebihan sesuatu kemahiran itu hanya mampu dinilai oleh mereka yang mempunyai kemahiran yang sama.', 'order' => 815],
            ['start_time' => 2540.16, 'end_time' => 2544.42, 'target_text' => 'It takes a Qari al-Quran to recognize another Qari al-Quran.', 'source_text' => 'Ia memerlukan seorang qari al-Quran untuk mengenali mutu bacaan qari al-Quran yang lain.', 'order' => 816],
            ['start_time' => 2544.52, 'end_time' => 2547.06, 'target_text' => 'The rest of the public THEY SAY, "MASHA ALLAH!', 'source_text' => 'Orang awam yang lain sekadar bersorak, "MASYA-ALLAH!', 'order' => 817],
            ['start_time' => 2547.16, 'end_time' => 2549.86, 'target_text' => 'TAKBIR!" AND THE Sheikh sitting in the front says, "You know what?', 'source_text' => 'TAKBIR!" Namun tuan guru syeikh yang duduk di saf hadapan berkata, "Tahukah kamu?', 'order' => 818],
            ['start_time' => 2549.96, 'end_time' => 2551.42, 'target_text' => 'He couldn\'t pronounce his Qaf.', 'source_text' => 'Dia tadi gagal menyebut huruf Qaf dengan tepat.', 'order' => 819],
            ['start_time' => 2551.52, 'end_time' => 2556.02, 'target_text' => 'Instead of Qalb, he says Kalb." Inna fi dhalika la dhikra liman kana lahu Kalb.', 'source_text' => 'Daripada menyebut Qalb (hati), dia menyebut Kalb (anjing)." Inna fi dhalika la dhikra liman kana lahu Kalb.', 'order' => 820],
            ['start_time' => 2556.12, 'end_time' => 2558.1, 'target_text' => 'La hawla wala quwwata illa billah.', 'source_text' => 'La hawla wala quwwata illa billah.', 'order' => 821],
            ['start_time' => 2558.2, 'end_time' => 2561.06, 'target_text' => 'I corrected one brother who said that and he got upset with me.', 'source_text' => 'Saya pernah menegur seorang jemaah lelaki yang membaca begitu lalu dia berasa kecil hati dan marah kepada saya.', 'order' => 822],
            ['start_time' => 2561.16, 'end_time' => 2566.34, 'target_text' => 'I said, "Habibi, if you know Arabic, you will know what you said is haram.', 'source_text' => 'Saya berkata kepadanya, "Habibi, sekiranya anda memahami bahasa Arab, anda akan tahu bahawa apa yang anda baca tadi membawa erti yang rosak.', 'order' => 823],
            ['start_time' => 2566.44, 'end_time' => 2567.82, 'target_text' => 'It\'s not allowed.', 'source_text' => 'Ia tidak dibenarkan.', 'order' => 824],
            ['start_time' => 2567.92, 'end_time' => 2570.58, 'target_text' => 'Qalb is a heart and Kalb is a dog.', 'source_text' => 'Qalb (dengan huruf Qaf) bermaksud hati nurani, manakala Kalb (dengan huruf Kaf) bermaksud anjing.', 'order' => 825],
            ['start_time' => 2570.68, 'end_time' => 2571.78, 'target_text' => 'And you are saying Kalb.', 'source_text' => 'Dan anda tadi telah menyebut perkataan Kalb (anjing).', 'order' => 826],
            ['start_time' => 2571.88, 'end_time' => 2572.46, 'target_text' => 'Come on, man.', 'source_text' => 'Bertenanglah, wahai saudaraku.', 'order' => 827],
            ['start_time' => 2572.56, 'end_time' => 2573.3, 'target_text' => 'Relax.', 'source_text' => 'Bertenang.', 'order' => 828],
            ['start_time' => 2573.4, 'end_time' => 2574.3, 'target_text' => 'Don\'t feel bad.', 'source_text' => 'Jangan berasa tersinggung.', 'order' => 829],
            ['start_time' => 2574.4, 'end_time' => 2575.62, 'target_text' => 'It\'s the word of Allah.', 'source_text' => 'Ini adalah kalam Allah.', 'order' => 830],
            ['start_time' => 2575.72, 'end_time' => 2576.58, 'target_text' => 'You need to be corrected.', 'source_text' => 'Wajib bagi anda untuk menerima pembetulan.', 'order' => 831],
            ['start_time' => 2576.68, 'end_time' => 2583.02, 'target_text' => 'When the Imam comes up, no matter who the Imam is, Imam of the Haram, if someone corrects him at the back and he feels bad,', 'source_text' => 'Apabila imam melangkah ke hadapan mengimami solat, tidak kira siapa imam tersebut — sekalipun Imam Masjidil Haram — sekiranya jemaah di belakang menegur kesilapan ayatnya lalu dia berasa malu,', 'order' => 832],
            ['start_time' => 2583.12, 'end_time' => 2583.7, 'target_text' => 'what will happen?', 'source_text' => 'apakah yang bakal berlaku?', 'order' => 833],
            ['start_time' => 2583.8, 'end_time' => 2584.46, 'target_text' => 'Do they feel bad?', 'source_text' => 'Adakah para imam di Masjidil Haram berasa tersinggung?', 'order' => 834],
            ['start_time' => 2584.56, 'end_time' => 2585.18, 'target_text' => 'They don\'t feel bad.', 'source_text' => 'Mereka langsung tidak berasa kecil hati.', 'order' => 835],
            ['start_time' => 2585.28, 'end_time' => 2586.14, 'target_text' => 'You know what I love?', 'source_text' => 'Tahukah anda apa yang amat saya kagumi?', 'order' => 836],
            ['start_time' => 2586.24, 'end_time' => 2588.02, 'target_text' => 'When I was young, I used to do Tarawih.', 'source_text' => 'Ketika zaman muda saya dahulu, saya sering mengimami solat tarawih.', 'order' => 837],
            ['start_time' => 2588.12, 'end_time' => 2590.66, 'target_text' => 'From the age of 14, I was the Imam in the masjid.', 'source_text' => 'Sejak berumur 14 tahun lagi, saya telah diberi amanah menjadi imam di masjid.', 'order' => 838],
            ['start_time' => 2590.76, 'end_time' => 2591.54, 'target_text' => 'I used to lead Tarawih.', 'source_text' => 'Saya sering mengimami solat tarawih.', 'order' => 839],
            ['start_time' => 2591.64, 'end_time' => 2596.46, 'target_text' => 'Full Quran I used to lead in some instances and some uh a portion of it.', 'source_text' => 'Kadangkala saya mengimami khatam 30 juzuk al-Quran sepenuhnya, dan kadangkala sebahagian daripadanya.', 'order' => 840],
            ['start_time' => 2596.56, 'end_time' => 2600.22, 'target_text' => 'And when someone corrects us, they don\'t even give you a moment and they fire.', 'source_text' => 'Dan apabila seseorang makmum menegur kesilapan ayat, mereka tidak menunggu walau sesaat dan terus menyergah menegur.', 'order' => 841],
            ['start_time' => 2600.32, 'end_time' => 2601.86, 'target_text' => 'And we used to feel bad.', 'source_text' => 'Dan dahulu kami sering berasa tersinggung di dalam hati.', 'order' => 842],
            ['start_time' => 2601.96, 'end_time' => 2605.86, 'target_text' => 'We used to feel, "Hey, at least give me a few moments." When you know, this guy here, he\'s just whacking it.', 'source_text' => 'Dahulu kami berbisik, "Aduh, berilah peluang beberapa saat dahulu untuk saya ingat kembali." Tetapi jemaah di belakang terus menegur dengan pantas.', 'order' => 843],
            ['start_time' => 2605.96, 'end_time' => 2608.06, 'target_text' => 'And then I went to Mecca.', 'source_text' => 'Kemudian saya berpeluang menjejakkan kaki ke Makkah.', 'order' => 844],
            ['start_time' => 2608.16, 'end_time' => 2612.22, 'target_text' => 'When I went to Mecca, it was 1988 in Ramadan.', 'source_text' => 'Ketika saya pergi ke Makkah pada bulan Ramadan tahun 1988.', 'order' => 845],
            ['start_time' => 2612.32, 'end_time' => 2614.06, 'target_text' => 'There were three Imams in Mecca.', 'source_text' => 'Pada waktu itu terdapat tiga orang imam utama di Makkah.', 'order' => 846],
            ['start_time' => 2614.16, 'end_time' => 2617.34, 'target_text' => 'They used to read the whole Tarawih one day, one day, one day.', 'source_text' => 'Mereka mengimami solat tarawih bergilir-gilir secara penuh — sehari seorang imam, kemudian imam seterusnya.', 'order' => 847],
            ['start_time' => 2617.44, 'end_time' => 2618.62, 'target_text' => 'Do you know who they were?', 'source_text' => 'Tahukah anda siapakah mereka?', 'order' => 848],
            ['start_time' => 2618.72, 'end_time' => 2620.94, 'target_text' => 'The first day, Sheikh Abdur Rahman as-Sudais.', 'source_text' => 'Malam pertama diimami oleh Sheikh Abdur Rahman as-Sudais.', 'order' => 849],
            ['start_time' => 2621.04, 'end_time' => 2623.46, 'target_text' => 'The second day, Sheikh Ali Abdullah Jabir.', 'source_text' => 'Malam kedua diimami oleh Sheikh Ali Abdullah Jabir.', 'order' => 850],
            ['start_time' => 2623.56, 'end_time' => 2626.94, 'target_text' => 'And the third day, Sheikh Ali Abdur Rahman al-Hudaifi.', 'source_text' => 'Dan malam ketiga diimami oleh Sheikh Ali Abdur Rahman al-Hudaifi.', 'order' => 851],
            ['start_time' => 2627.04, 'end_time' => 2629.94, 'target_text' => 'This was in Mecca in 1988, right?', 'source_text' => 'Peristiwa ini berlaku di Makkah pada tahun 1988, betul bukan?', 'order' => 852],
            ['start_time' => 2630.04, 'end_time' => 2631.06, 'target_text' => 'These were the three Imams.', 'source_text' => 'Merekalah tiga orang imam besar pada ketika itu.', 'order' => 853],
            ['start_time' => 2631.16, 'end_time' => 2632.38, 'target_text' => 'They used to rotate.', 'source_text' => 'Mereka mengimami solat secara bergilir-gilir.', 'order' => 854],
            ['start_time' => 2632.48, 'end_time' => 2633.58, 'target_text' => 'Now, what happened?', 'source_text' => 'Apakah yang berlaku?', 'order' => 855],
            ['start_time' => 2633.68, 'end_time' => 2638.78, 'target_text' => 'When one makes a mistake, they are corrected and they carry on like nothing happened.', 'source_text' => 'Apabila salah seorang imam tersilap ayat, makmum di belakang menegur dan imam tersebut meneruskan bacaan seperti tiada apa-apa yang berlaku.', 'order' => 856],
            ['start_time' => 2638.88, 'end_time' => 2639.54, 'target_text' => 'They continue.', 'source_text' => 'Mereka terus membaca dengan tenang.', 'order' => 857],
            ['start_time' => 2639.64, 'end_time' => 2640.42, 'target_text' => 'No one felt bad.', 'source_text' => 'Tiada seorang pun berasa tersinggung atau malu.', 'order' => 858],
            ['start_time' => 2640.52, 'end_time' => 2641.58, 'target_text' => 'The tune doesn\'t change.', 'source_text' => 'Alunan taranum mereka langsung tidak berubah sumbang.', 'order' => 859],
            ['start_time' => 2641.68, 'end_time' => 2644.06, 'target_text' => 'When I used to be corrected, the tune used to change.', 'source_text' => 'Dahulu ketika saya ditegur kesilapan, alunan suara saya terus berubah serak.', 'order' => 860],
            ['start_time' => 2644.16, 'end_time' => 2645.74, 'target_text' => 'I used to feel upset and like I want to give up.', 'source_text' => 'Dahulu saya berasa kecewa dan rasa hendak berundur mengalah.', 'order' => 861],
            ['start_time' => 2645.84, 'end_time' => 2646.26, 'target_text' => 'Okay, خلاص.', 'source_text' => '"Sudahlah, cukuplah.', 'order' => 862],
            ['start_time' => 2646.36, 'end_time' => 2647.46, 'target_text' => 'You made two, three mistakes.', 'source_text' => 'Kamu dah buat dua tiga kesilapan tadi."', 'order' => 863],
            ['start_time' => 2647.56, 'end_time' => 2650.94, 'target_text' => 'Now I\'m I\'m slumped and I feel like you know I\'m punctured.', 'source_text' => 'Lalu saya berasa jatuh semangat dan rasa bagaikan \'tayar yang bocor\'.', 'order' => 864],
            ['start_time' => 2651.04, 'end_time' => 2651.86, 'target_text' => 'Why?', 'source_text' => 'Mengapa?', 'order' => 865],
            ['start_time' => 2651.96, 'end_time' => 2654.42, 'target_text' => 'Who do you want to impress that you did not make mistakes?', 'source_text' => 'Siapakah yang ingin anda kagumkan kononnya anda tidak pernah melakukan kesilapan?', 'order' => 866],
            ['start_time' => 2654.52, 'end_time' => 2656.58, 'target_text' => 'No, I want to impress Allah.', 'source_text' => 'Tidak, niat saya hanyalah semata-mata mencari keredaan Allah.', 'order' => 867],
            ['start_time' => 2656.68, 'end_time' => 2660.34, 'target_text' => 'Oh Allah, I was corrected and I took the correction because this is your word.', 'source_text' => '"Ya Allah, aku ditegur dan aku menerima teguran ini kerana ini adalah kalam suci-Mu.', 'order' => 868],
            ['start_time' => 2660.44, 'end_time' => 2662.82, 'target_text' => 'It\'s not It\'s not anyone\'s book.', 'source_text' => 'Ini bukan buku karangan mana-mana manusia biasa."', 'order' => 869],
            ['start_time' => 2662.92, 'end_time' => 2664.34, 'target_text' => 'I felt good.', 'source_text' => 'Maka saya berasa amat tenang dan lapang dada.', 'order' => 870],
            ['start_time' => 2664.44, 'end_time' => 2665.66, 'target_text' => 'Allahu Akbar.', 'source_text' => 'Allahu Akbar.', 'order' => 871],
            ['start_time' => 2665.76, 'end_time' => 2667.26, 'target_text' => 'So', 'source_text' => 'Oleh itu,', 'order' => 872],
            ['start_time' => 2667.36, 'end_time' => 2669.18, 'target_text' => 'feel good when someone corrects you.', 'source_text' => 'berlapang dadalah dan berasa gembiralah apabila seseorang menegur kesilapan anda.', 'order' => 873],
            ['start_time' => 2669.28, 'end_time' => 2670.38, 'target_text' => 'After that I learned.', 'source_text' => 'Sejak daripada peristiwa itulah saya belajar menjadi matang.', 'order' => 874],
            ['start_time' => 2670.48, 'end_time' => 2672.78, 'target_text' => 'Now correct me, I will not feel bad.', 'source_text' => 'Kini sekiranya anda menegur saya, saya tidak akan berasa kecil hati lagi.', 'order' => 875],
            ['start_time' => 2672.88, 'end_time' => 2673.9, 'target_text' => 'Because I realized you know what?', 'source_text' => 'Kerana saya sedar bahawa tahukah anda?', 'order' => 876],
            ['start_time' => 2674.0, 'end_time' => 2677.46, 'target_text' => 'You want to be Imam You must not feel bad when you are corrected.', 'source_text' => 'Sekiranya anda ingin menjadi seorang imam, anda tidak boleh berasa tersinggung apabila ditegur.', 'order' => 877],
            ['start_time' => 2677.56, 'end_time' => 2679.1, 'target_text' => 'Up to today they they are excited.', 'source_text' => 'Sehingga ke hari ini para imam di sana sentiasa berlapang dada.', 'order' => 878],
            ['start_time' => 2679.2, 'end_time' => 2683.9, 'target_text' => 'You correct any one of them subhanallah they will take the correction and keep it moving as though nothing happened because', 'source_text' => 'Sekiranya anda menegur mana-mana seorang daripada mereka, subhanallah mereka menerima teguran tersebut dan meneruskan bacaan seolah-olah tiada apa yang berlaku kerana menyedari', 'order' => 879],
            ['start_time' => 2684.0, 'end_time' => 2684.74, 'target_text' => 'human beings.', 'source_text' => 'hakikat sifat manusia biasa.', 'order' => 880],
            ['start_time' => 2684.84, 'end_time' => 2688.54, 'target_text' => 'And sometimes there a lot of mistakes that happen in the Haram, a lot.', 'source_text' => 'Dan kadangkala terdapat juga kesilapan yang berlaku dalam bacaan di Masjidil Haram, banyak kali juga.', 'order' => 881],
            ['start_time' => 2688.64, 'end_time' => 2690.06, 'target_text' => 'Because everyone is a human.', 'source_text' => 'Kerana setiap insan adalah manusia biasa.', 'order' => 882],
            ['start_time' => 2690.16, 'end_time' => 2694.5, 'target_text' => 'The point I\'m raising here is let\'s not justify when we are corrected.', 'source_text' => 'Intipati yang ingin saya tekankan di sini adalah marilah kita jangan mencari alasan membela diri apabila kita ditegur.', 'order' => 883],
            ['start_time' => 2694.6, 'end_time' => 2695.54, 'target_text' => 'I want to correct myself.', 'source_text' => 'Saya sentiasa ingin memperbaiki diri saya.', 'order' => 884],
            ['start_time' => 2695.64, 'end_time' => 2699.42, 'target_text' => 'I need that scale on that day of judgement to be tipped on the right side.', 'source_text' => 'Saya amat mendambakan timbangan mizan pada hari kiamat kelak menjadi berat di sebelah kanan.', 'order' => 885],
            ['start_time' => 2699.52, 'end_time' => 2703.54, 'target_text' => 'So keep on doing lots and lots and lots of good deeds by the help and the will of Allah.', 'source_text' => 'Maka teruskanlah melipatgandakan sebanyak mungkin amalan kebajikan dengan pertolongan dan kehendak Allah.', 'order' => 886],
            ['start_time' => 2703.64, 'end_time' => 2706.18, 'target_text' => 'So we start off by seeking the forgiveness of Allah.', 'source_text' => 'Maka langkah pertama kita bermula dengan memohon keampunan (istighfar) daripada Allah.', 'order' => 887],
            ['start_time' => 2706.28, 'end_time' => 2707.78, 'target_text' => 'Secondly,', 'source_text' => 'Keduanya,', 'order' => 888],
            ['start_time' => 2707.88, 'end_time' => 2708.78, 'target_text' => 'humble yourself.', 'source_text' => 'rendahkanlah hati anda dengan sifat tawaduk.', 'order' => 889],
            ['start_time' => 2708.88, 'end_time' => 2715.16, 'target_text' => 'Become a person who is not arrogant because with arrogance you\'re not going to go far in life.', 'source_text' => 'Jadilah insan yang tidak takbur dan sombong kerana sifat sombong tidak akan membawa anda ke mana-mana dalam hidup ini.', 'order' => 890],
            ['start_time' => 2719.36, 'end_time' => 2720.3, 'target_text' => 'Hadith.', 'source_text' => 'Sabda hadis Nabi Sallallahu Alaihi Wasallam.', 'order' => 891],
            ['start_time' => 2720.4, 'end_time' => 2725.1, 'target_text' => 'He will not enter paradise in whose heart is even a droplet of pride.', 'source_text' => 'Tidak akan masuk syurga sesiapa yang di dalam hatinya terdapat sebesar zarah perasaan sombong takbur.', 'order' => 892],
            ['start_time' => 2725.2, 'end_time' => 2725.7, 'target_text' => 'Remove the pride.', 'source_text' => 'Buangkanlah rasa takbur itu.', 'order' => 893],
            ['start_time' => 2725.8, 'end_time' => 2726.34, 'target_text' => 'Who am I?', 'source_text' => 'Siapakah saya ini?', 'order' => 894],
            ['start_time' => 2726.44, 'end_time' => 2727.3, 'target_text' => 'I\'m your brother.', 'source_text' => 'Saya hanyalah saudara anda.', 'order' => 895],
            ['start_time' => 2727.4, 'end_time' => 2728.26, 'target_text' => 'Alas.', 'source_text' => 'Cukup sekadar itu.', 'order' => 896],
            ['start_time' => 2728.36, 'end_time' => 2734.54, 'target_text' => 'If I complete this talk well I if the masjid was maybe half full quarter full, I would have probably sat later on greeted', 'source_text' => 'Sekiranya saya selesai menyampaikan ceramah ini — sekiranya jemaah di masjid ini separuh atau suku sahaja yang hadir, saya pasti akan duduk lebih lama bersalaman dengan', 'order' => 897],
            ['start_time' => 2734.64, 'end_time' => 2737.3, 'target_text' => 'everyone and you know shaken hands with the people and so on.', 'source_text' => 'semua orang, beramah mesra dan berjabat tangan dengan para jemaah sekalian.', 'order' => 898],
            ['start_time' => 2737.4, 'end_time' => 2738.7, 'target_text' => 'But I have a duty.', 'source_text' => 'Namun saya mempunyai amanah dan tanggungjawab menjaga ketenteraman.', 'order' => 899],
            ['start_time' => 2738.8, 'end_time' => 2740.42, 'target_text' => 'This is a masjid it\'s packed.', 'source_text' => 'Ini rumah Allah dan suasananya terlalu padat dengan jemaah.', 'order' => 900],
            ['start_time' => 2740.52, 'end_time' => 2742.22, 'target_text' => 'If I\'m to greet you they will be stampeding.', 'source_text' => 'Sekiranya saya berdiri bersalaman dengan anda, pasti akan berlaku tolak-menolak dan kesesakan.', 'order' => 901],
            ['start_time' => 2742.32, 'end_time' => 2744.46, 'target_text' => 'They will be hurting of people, the kids and so on.', 'source_text' => 'Orang ramai mungkin akan tercedera, anak-anak kecil terhimpit dan sebagainya.', 'order' => 902],
            ['start_time' => 2744.56, 'end_time' => 2745.94, 'target_text' => 'It\'s my duty to walk out.', 'source_text' => 'Maka menjadi kewajipan saya untuk segera beredar keluar.', 'order' => 903],
            ['start_time' => 2746.04, 'end_time' => 2747.3, 'target_text' => 'Do you know what I do?', 'source_text' => 'Tahukah anda apa yang biasa saya lakukan?', 'order' => 904],
            ['start_time' => 2747.4, 'end_time' => 2749.62, 'target_text' => 'You invite me to a wedding for example.', 'source_text' => 'Katakanlah anda menjemput saya menghadiri majlis perkahwinan.', 'order' => 905],
            ['start_time' => 2749.72, 'end_time' => 2753.22, 'target_text' => 'I don\'t give preference to go to weddings but sometimes we have to go.', 'source_text' => 'Saya biasanya tidak mengutamakan menghadiri kenduri perkahwinan, namun kadangkala kita perlu hadir.', 'order' => 906],
            ['start_time' => 2753.32, 'end_time' => 2756.86, 'target_text' => 'So if I go to the wedding I\'ll tell the brother, brother I\'ll come but I leave immediately.', 'source_text' => 'Maka sekiranya saya hadir ke majlis perkahwinan itu, saya akan berpesan kepada tuan rumah, "Wahai saudaraku, saya akan hadir tetapi saya akan terus beredar sejurus selepas itu."', 'order' => 907],
            ['start_time' => 2756.96, 'end_time' => 2759.14, 'target_text' => 'I\'ll come do a talk, officiate and move.', 'source_text' => 'Saya hadir menyampaikan tazkirah ringkas, mendoakan keberkatan dan segera beredar.', 'order' => 908],
            ['start_time' => 2759.24, 'end_time' => 2759.66, 'target_text' => 'No, but why?', 'source_text' => 'Tuan rumah bertanya, "Kenapa begitu tergesa-gesa?"', 'order' => 909],
            ['start_time' => 2759.76, 'end_time' => 2762.68, 'target_text' => 'I said no, I have something to do.', 'source_text' => 'Saya menjawab, "Saya ada urusan lain yang perlu diselesaikan."', 'order' => 910],
            ['start_time' => 2763.12, 'end_time' => 2764.14, 'target_text' => 'What did I do?', 'source_text' => 'Tahukah anda mengapa saya bertindak sedemikian?', 'order' => 911],
            ['start_time' => 2764.24, 'end_time' => 2767.18, 'target_text' => 'That day belongs to the bride and the groom.', 'source_text' => 'Hari tersebut adalah hari bahagia milik pasangan pengantin lelaki dan perempuan.', 'order' => 912],
            ['start_time' => 2767.28, 'end_time' => 2774.26, 'target_text' => 'I\'m going to go there just because of a few likes and clicks that people have, the focus is going to change onto me.', 'source_text' => 'Sekiranya saya duduk berlama-lama di situ semata-mata kerana segelintir \'likes\' dan perhatian manusia, tumpuan majlis pasti akan beralih kepada diri saya.', 'order' => 913],
            ['start_time' => 2774.36, 'end_time' => 2776.42, 'target_text' => 'And everyone wants to take photos and they want to do that.', 'source_text' => 'Dan semua orang akan mengerumuni hendak mengambil gambar dan sebagainya.', 'order' => 914],
            ['start_time' => 2776.52, 'end_time' => 2777.5, 'target_text' => 'I don\'t need all of that.', 'source_text' => 'Saya langsung tidak memerlukan semua publisiti itu.', 'order' => 915],
            ['start_time' => 2777.6, 'end_time' => 2778.42, 'target_text' => 'And they don\'t need all of it.', 'source_text' => 'Dan mereka sendiri sebenarnya tidak memerlukannya.', 'order' => 916],
            ['start_time' => 2778.52, 'end_time' => 2778.92, 'target_text' => 'They don\'t know.', 'source_text' => 'Mereka tidak sedar.', 'order' => 917],
            ['start_time' => 2779.0, 'end_time' => 2781.42, 'target_text' => 'They\'re excited we\'ve invited this guy to the wedding.', 'source_text' => 'Mereka cuma berasa teruja kononnya berjaya menjemput penceramah ini ke majlis perkahwinan mereka.', 'order' => 918],
            ['start_time' => 2781.52, 'end_time' => 2782.3, 'target_text' => 'What did I do?', 'source_text' => 'Apakah yang saya lakukan?', 'order' => 919],
            ['start_time' => 2782.4, 'end_time' => 2786.18, 'target_text' => 'I went away as a blessing for me and for everyone else.', 'source_text' => 'Saya segera beredar sebagai suatu rahmat dan kebaikan bagi diri saya dan bagi semua orang yang hadir.', 'order' => 920],
            ['start_time' => 2786.28, 'end_time' => 2787.5, 'target_text' => 'I don\'t need the food.', 'source_text' => 'Saya tidak berniat untuk menikmati jamuan makanan.', 'order' => 921],
            ['start_time' => 2787.6, 'end_time' => 2790.38, 'target_text' => 'I just mashallah I delivered what I had to and I went away.', 'source_text' => 'Saya telah menyampaikan apa yang diamanahkan dan kemudian saya beredar dengan tenang.', 'order' => 922],
            ['start_time' => 2790.48, 'end_time' => 2793.1, 'target_text' => 'Now the focus remains on the people it\'s supposed to be on.', 'source_text' => 'Kini tumpuan majlis kekal terarah kepada mereka yang sepatutnya diraikan.', 'order' => 923],
            ['start_time' => 2793.2, 'end_time' => 2794.94, 'target_text' => 'It\'s your big day, your big day.', 'source_text' => 'Hari itu adalah hari bersejarah anda, hari bahagia anda.', 'order' => 924],
            ['start_time' => 2795.04, 'end_time' => 2796.54, 'target_text' => 'You wonder why I went.', 'source_text' => 'Anda mungkin tertanya-tanya mengapa saya segera pergi.', 'order' => 925],
            ['start_time' => 2796.64, 'end_time' => 2799.46, 'target_text' => 'Between me and Allah I know why I went.', 'source_text' => 'Antara diri saya dengan Allah, saya tahu apa niat sebenar saya berbuat demikian.', 'order' => 926],
            ['start_time' => 2799.56, 'end_time' => 2801.82, 'target_text' => 'The same applies here.', 'source_text' => 'Begitu juga halnya di sini pada malam ini.', 'order' => 927],
            ['start_time' => 2801.92, 'end_time' => 2804.22, 'target_text' => 'I\'m going to walk out straight after my talk and I\'m going to be gone.', 'source_text' => 'Saya akan melangkah keluar sebaik sahaja selesai menyampaikan ceramah dan saya akan terus beredar.', 'order' => 928],
            ['start_time' => 2804.32, 'end_time' => 2805.58, 'target_text' => 'Before you know it, the man is gone.', 'source_text' => 'Sebelum anda sempat menyedarinya, penceramah sudah pun beredar.', 'order' => 929],
            ['start_time' => 2805.68, 'end_time' => 2806.08, 'target_text' => 'Why?', 'source_text' => 'Mengapa?', 'order' => 930],
            ['start_time' => 2806.12, 'end_time' => 2806.66, 'target_text' => 'Who am I?', 'source_text' => 'Siapakah diri saya ini?', 'order' => 931],
            ['start_time' => 2806.76, 'end_time' => 2809.94, 'target_text' => 'If there was any virtue in shaking my hand, I\'d shake everybody\'s hand.', 'source_text' => 'Sekiranya ada fadhilat istimewa dengan bersalaman dengan tangan saya, nescaya saya akan bersalaman dengan setiap orang yang ada.', 'order' => 932],
            ['start_time' => 2810.04, 'end_time' => 2811.22, 'target_text' => 'There\'s no virtue.', 'source_text' => 'Namun tiada keistimewaan luar biasa padanya.', 'order' => 933],
            ['start_time' => 2811.32, 'end_time' => 2813.22, 'target_text' => 'You shake my hand doesn\'t mean a thing.', 'source_text' => 'Bersalaman dengan saya langsung tidak menjamin apa-apa.', 'order' => 934],
            ['start_time' => 2813.32, 'end_time' => 2816.56, 'target_text' => 'Again, in Allahhi', 'source_text' => 'Sekali lagi, di sisi Allah...', 'order' => 935],
            ['start_time' => 2817.64, 'end_time' => 2819.1, 'target_text' => 'You know, so I\'m a human like you.', 'source_text' => 'Saya hanyalah manusia biasa seperti anda semua.', 'order' => 936],
            ['start_time' => 2819.2, 'end_time' => 2820.62, 'target_text' => 'You\'re probably better than me.', 'source_text' => 'Anda mungkin jauh lebih mulia di sisi Allah daripada diri saya.', 'order' => 937],
            ['start_time' => 2820.72, 'end_time' => 2822.14, 'target_text' => 'But I\'m just here to remind you.', 'source_text' => 'Saya hadir di sini sekadar untuk saling mengingatkan.', 'order' => 938],
            ['start_time' => 2822.24, 'end_time' => 2824.06, 'target_text' => 'Maybe you want to listen to me.', 'source_text' => 'Mungkin anda sudi mendengarkan nasihat saya.', 'order' => 939],
            ['start_time' => 2824.16, 'end_time' => 2825.74, 'target_text' => 'And maybe you want to hear a few things.', 'source_text' => 'Dan mungkin anda ingin mendengar beberapa patah pesanan.', 'order' => 940],
            ['start_time' => 2825.84, 'end_time' => 2826.58, 'target_text' => 'It\'s a reminder.', 'source_text' => 'Ia adalah suatu peringatan bersama.', 'order' => 941],
            ['start_time' => 2826.68, 'end_time' => 2829.3, 'target_text' => 'I need this reminder more than you do.', 'source_text' => 'Malah saya sendiri amat memerlukan peringatan ini melebihi diri anda.', 'order' => 942],
            ['start_time' => 2829.4, 'end_time' => 2831.26, 'target_text' => 'But mashallah I will I don\'t mind.', 'source_text' => 'Namun masya-Allah saya tidak keberatan.', 'order' => 943],
            ['start_time' => 2831.36, 'end_time' => 2834.18, 'target_text' => 'We can shake hands because it\'s it\'s a good sunnah.', 'source_text' => 'Kita boleh bersalaman kerana ia adalah amalan sunnah yang sangat dituntut.', 'order' => 944],
            ['start_time' => 2834.28, 'end_time' => 2840.78, 'target_text' => 'But when you know there is a negative side to it and they may be stampeding and there\'s going to be so much of chaos, the', 'source_text' => 'Namun apabila anda menyedari ada risiko kemudaratan di mana jemaah mungkin berasak-asak dan timbul kekecohan yang tidak terkawal, perkara', 'order' => 945],
            ['start_time' => 2840.88, 'end_time' => 2846.06, 'target_text' => 'best thing for you to do is to bismillah salaam alaikum my brothers, my sisters and you walk away.', 'source_text' => 'terbaik yang wajar anda lakukan adalah dengan melafazkan, "Bismillah, assalamu alaykum wahai saudara-saudariku," lalu beredar dengan tenang.', 'order' => 946],
            ['start_time' => 2846.16, 'end_time' => 2847.78, 'target_text' => 'You feel You hear what I\'m saying?', 'source_text' => 'Adakah anda memahami maksud yang saya sampaikan ini?', 'order' => 947],
            ['start_time' => 2847.88, 'end_time' => 2849.74, 'target_text' => 'May Allah grant us Jannah.', 'source_text' => 'Semoga Allah mengurniakan syurga kepada kita semua.', 'order' => 948],
            ['start_time' => 2849.84, 'end_time' => 2851.22, 'target_text' => 'May Allah almighty grant us Jannah.', 'source_text' => 'Semoga Allah Yang Maha Berkuasa mengurniakan Jannatul Firdaus kepada kita semua.', 'order' => 949],
            ['start_time' => 2851.32, 'end_time' => 2853.94, 'target_text' => 'The point I\'m raising, second thing is you need to humble yourself.', 'source_text' => 'Intipati penting yang saya kemukakan, perkara kedua adalah anda wajib merendahkan ego dan bersikap tawaduk.', 'order' => 950],
            ['start_time' => 2854.04, 'end_time' => 2860.3, 'target_text' => 'Third thing, the third thing when you want to change your life and you want that scale to tip in the proper way, learn to', 'source_text' => 'Perkara ketiga — rukun ketiga apabila anda ingin mengubah haluan hidup anda dan mendambakan neraca mizan condong ke sebelah kanan, belajarlah', 'order' => 951],
            ['start_time' => 2860.4, 'end_time' => 2863.22, 'target_text' => 'pray five times a day.', 'source_text' => 'untuk mendirikan solat lima waktu sehari semalam secara istiqamah.', 'order' => 952],
            ['start_time' => 2863.32, 'end_time' => 2865.66, 'target_text' => 'Learn to pray five times a day.', 'source_text' => 'Belajarlah menjaga solat fardu lima waktu.', 'order' => 953],
            ['start_time' => 2865.76, 'end_time' => 2876.62, 'target_text' => 'PUSH YOURSELF HARD HARD HARD because that is the only pillar of Islam after the shahada that nobody has an excuse not to engage', 'source_text' => 'PAKSA DAN DISIPLINKAN DIRI ANDA BERSUNGGUH-SUNGGUH kerana solat adalah satu-satunya rukun Islam selepas syahadah yang tiada sesiapa pun mempunyai alasan untuk mengabaikannya,', 'order' => 954],
            ['start_time' => 2876.72, 'end_time' => 2878.46, 'target_text' => 'in.', 'source_text' => 'walau dalam apa jua keadaan sekalipun.', 'order' => 955],
            ['start_time' => 2878.56, 'end_time' => 2879.54, 'target_text' => 'You know what I mean?', 'source_text' => 'Fahamkah anda apa yang saya maksudkan?', 'order' => 956],
            ['start_time' => 2879.64, 'end_time' => 2880.7, 'target_text' => 'I said it before.', 'source_text' => 'Saya pernah menyebutnya sebelum ini.', 'order' => 957],
            ['start_time' => 2880.8, 'end_time' => 2882.62, 'target_text' => 'Can tell you quickly.', 'source_text' => 'Boleh saya terangkan kepada anda secara ringkas.', 'order' => 958],
            ['start_time' => 2882.72, 'end_time' => 2884.22, 'target_text' => 'How many pillars in Islam?', 'source_text' => 'Berapakah rukun di dalam Islam?', 'order' => 959],
            ['start_time' => 2884.32, 'end_time' => 2884.78, 'target_text' => 'Five.', 'source_text' => 'Lima.', 'order' => 960],
            ['start_time' => 2884.88, 'end_time' => 2885.28, 'target_text' => 'Five.', 'source_text' => 'Ya, lima rukun.', 'order' => 961],
            ['start_time' => 2885.36, 'end_time' => 2887.82, 'target_text' => 'When you want to enter Islam, what do you say?', 'source_text' => 'Apabila anda ingin memeluk Islam, apakah yang anda lafazkan?', 'order' => 962],
            ['start_time' => 2887.92, 'end_time' => 2888.66, 'target_text' => 'Shahada, right?', 'source_text' => 'Dua kalimah syahadah, betul bukan?', 'order' => 963],
            ['start_time' => 2888.76, 'end_time' => 2889.9, 'target_text' => 'So, that\'s first pillar done.', 'source_text' => 'Maka rukun pertama telah terlaksana.', 'order' => 964],
            ['start_time' => 2890.0, 'end_time' => 2891.06, 'target_text' => 'There\'s no no compromise.', 'source_text' => 'Tiada tolak ansur padanya.', 'order' => 965],
            ['start_time' => 2891.16, 'end_time' => 2892.34, 'target_text' => 'That\'s the entry into faith.', 'source_text' => 'Itulah pintu gerbang masuk ke dalam keimanan.', 'order' => 966],
            ['start_time' => 2892.44, 'end_time' => 2893.22, 'target_text' => 'Right.', 'source_text' => 'Baiklah.', 'order' => 967],
            ['start_time' => 2893.32, 'end_time' => 2894.46, 'target_text' => 'Let\'s go from the bottom.', 'source_text' => 'Mari kita teliti dari rukun yang paling bawah.', 'order' => 968],
            ['start_time' => 2894.56, 'end_time' => 2895.78, 'target_text' => 'The last pillar is Hajj.', 'source_text' => 'Rukun Islam yang terakhir adalah ibadah Haji.', 'order' => 969],
            ['start_time' => 2895.88, 'end_time' => 2898.94, 'target_text' => 'If you don\'t have money, is it applicable to you?', 'source_text' => 'Sekiranya anda tidak mempunyai kemampuan kewangan, adakah haji wajib ke atas anda?', 'order' => 970],
            ['start_time' => 2899.04, 'end_time' => 2902.18, 'target_text' => 'I believe it a pillar, but I didn\'t fulfill it cuz I don\'t have to.', 'source_text' => 'Saya meyakininya sebagai rukun, tetapi saya tidak menunaikannya kerana saya belum berkemampuan.', 'order' => 971],
            ['start_time' => 2902.28, 'end_time' => 2903.06, 'target_text' => 'Zakat.', 'source_text' => 'Seterusnya, Zakat.', 'order' => 972],
            ['start_time' => 2903.16, 'end_time' => 2907.22, 'target_text' => 'Zakat, you believe it as a pillar, but if you don\'t have wealth, is it applicable to you to fulfill?', 'source_text' => 'Zakat, anda meyakininya sebagai rukun Islam, namun jika anda tidak memiliki harta yang mencukupi nisab, adakah anda diwajibkan mengeluarkannya?', 'order' => 973],
            ['start_time' => 2907.32, 'end_time' => 2908.38, 'target_text' => 'No.', 'source_text' => 'Tidak wajib.', 'order' => 974],
            ['start_time' => 2908.48, 'end_time' => 2909.3, 'target_text' => 'Let\'s go to the next one.', 'source_text' => 'Mari kita beralih ke rukun seterusnya.', 'order' => 975],
            ['start_time' => 2909.4, 'end_time' => 2910.1, 'target_text' => 'Fasting.', 'source_text' => 'Ibadah Puasa.', 'order' => 976],
            ['start_time' => 2910.2, 'end_time' => 2912.22, 'target_text' => 'Fasting is a very important pillar.', 'source_text' => 'Puasa adalah rukun Islam yang amat penting.', 'order' => 977],
            ['start_time' => 2912.32, 'end_time' => 2918.26, 'target_text' => 'I believe it, but if you are unwell or sick and you cannot fast, does Allah compel you to fast?', 'source_text' => 'Saya meyakininya, namun sekiranya anda uzur atau terlantar sakit dan tidak mampu berpuasa, adakah Allah memaksa anda berpuasa?', 'order' => 978],
            ['start_time' => 2918.36, 'end_time' => 2918.76, 'target_text' => 'No.', 'source_text' => 'Tidak sama sekali.', 'order' => 979],
            ['start_time' => 2918.8, 'end_time' => 2919.66, 'target_text' => 'You can do a fidiya.', 'source_text' => 'Anda boleh menggantikannya dengan membayar fidyah.', 'order' => 980],
            ['start_time' => 2919.76, 'end_time' => 2921.38, 'target_text' => 'There are other ways of dealing with it.', 'source_text' => 'Terdapat jalan keluar syariat untuk menanganinya.', 'order' => 981],
            ['start_time' => 2921.48, 'end_time' => 2923.5, 'target_text' => 'But come to salah.', 'source_text' => 'Tetapi apabila tiba kepada kewajipan Solat.', 'order' => 982],
            ['start_time' => 2923.6, 'end_time' => 2925.86, 'target_text' => 'You can\'t read it standing, what do you do?', 'source_text' => 'Sekiranya anda tidak mampu solat berdiri, apakah yang anda lakukan?', 'order' => 983],
            ['start_time' => 2925.96, 'end_time' => 2926.36, 'target_text' => 'You sit.', 'source_text' => 'Anda solat secara duduk.', 'order' => 984],
            ['start_time' => 2926.36, 'end_time' => 2927.78, 'target_text' => 'You can\'t sit, what do you do?', 'source_text' => 'Sekiranya anda tidak mampu duduk, apa yang anda lakukan?', 'order' => 985],
            ['start_time' => 2927.88, 'end_time' => 2928.42, 'target_text' => 'You lie down.', 'source_text' => 'Anda solat secara berbaring.', 'order' => 986],
            ['start_time' => 2928.52, 'end_time' => 2931.42, 'target_text' => 'You can\'t use the water and do wudu, what do you do?', 'source_text' => 'Sekiranya anda tidak boleh menggunakan air untuk berwuduk, apa yang anda lakukan? Anda bertayammum.', 'order' => 987],
            ['start_time' => 2931.52, 'end_time' => 2934.06, 'target_text' => 'But you will always have to pray.', 'source_text' => 'Namun anda tetap diwajibkan untuk mendirikan solat dalam apa jua keadaan.', 'order' => 988],
            ['start_time' => 2934.16, 'end_time' => 2934.94, 'target_text' => 'Prayer.', 'source_text' => 'Ibadah solat.', 'order' => 989],
            ['start_time' => 2935.04, 'end_time' => 2936.9, 'target_text' => 'So, you want to build a connection with Allah.', 'source_text' => 'Maka sekiranya anda ingin membina hubungan yang akrab dengan Allah.', 'order' => 990],
            ['start_time' => 2937.0, 'end_time' => 2938.9, 'target_text' => 'Do you know what Allah says?', 'source_text' => 'Tahukah anda apa yang Allah firmankan?', 'order' => 991],
            ['start_time' => 2939.0, 'end_time' => 2944.7, 'target_text' => 'Allah says there is nothing more beloved unto me than those things which I made compulsory.', 'source_text' => 'Allah berfirman bahawa tiada amalan yang lebih Aku cintai melainkan amalan-amalan yang telah Aku fardukan ke atas hamba-Ku.', 'order' => 992],
            ['start_time' => 2944.8, 'end_time' => 2946.86, 'target_text' => 'That\'s a Hadith Qudsi.', 'source_text' => 'Itulah sabda Hadis Qudsi yang agung.', 'order' => 993],
            ['start_time' => 2946.96, 'end_time' => 2951.14, 'target_text' => 'There is nothing more beloved to me than those things which I made compulsory.', 'source_text' => 'Tiada perkara yang lebih Aku cintai melainkan amalan yang telah Aku fardukan ke atas hamba-Ku.', 'order' => 994],
            ['start_time' => 2951.24, 'end_time' => 2955.1, 'target_text' => 'If I made something compulsory, it means I love it the most.', 'source_text' => 'Sekiranya Aku memfardukan sesuatu amalan, itu bermakna amalan itulah yang paling Aku cintai.', 'order' => 995],
            ['start_time' => 2955.2, 'end_time' => 2957.98, 'target_text' => 'And one of the first things he made compulsory is the five prayers.', 'source_text' => 'Dan antara perkara terawal yang difardukan oleh Allah adalah solat lima waktu.', 'order' => 996],
            ['start_time' => 2958.08, 'end_time' => 2959.94, 'target_text' => 'So, you want to connect with Allah.', 'source_text' => 'Maka, sekiranya anda ingin mendekatkan diri kepada Allah.', 'order' => 997],
            ['start_time' => 2960.04, 'end_time' => 2961.02, 'target_text' => 'I know we\'re weak.', 'source_text' => 'Saya sedar kita semua insan yang lemah.', 'order' => 998],
            ['start_time' => 2961.12, 'end_time' => 2962.86, 'target_text' => 'I know all of us have weakness.', 'source_text' => 'Saya tahu kita semua mempunyai kekurangan diri.', 'order' => 999],
            ['start_time' => 2962.96, 'end_time' => 2969.06, 'target_text' => 'My brothers, my sisters, my beloved children, I encourage you strongly.', 'source_text' => 'Wahai saudara-saudaraku, para saudariku, anak-anakku yang dikasihi, saya menyeru anda semua dengan penuh kesungguhan.', 'order' => 1000],
            ['start_time' => 2969.16, 'end_time' => 2970.26, 'target_text' => 'Become serious with your prayer.', 'source_text' => 'Ambillah berat dan bersungguh-sungguhlah menjaga solat anda.', 'order' => 1001],
            ['start_time' => 2970.36, 'end_time' => 2971.42, 'target_text' => 'Your life will change.', 'source_text' => 'Nescaya kehidupan anda pasti akan berubah menjadi lebih baik.', 'order' => 1002],
            ['start_time' => 2971.52, 'end_time' => 2972.9, 'target_text' => 'Be a proud Muslim.', 'source_text' => 'Jadilah seorang Muslim yang bangga dengan agamanya.', 'order' => 1003],
            ['start_time' => 2973.0, 'end_time' => 2975.26, 'target_text' => 'Be a person whose identity is known.', 'source_text' => 'Jadilah insan yang jelas dan teguh identiti Islamnya.', 'order' => 1004],
            ['start_time' => 2975.36, 'end_time' => 2978.38, 'target_text' => 'So what if they if they do not treat you well?', 'source_text' => 'Pedulikan apa sekiranya mereka tidak melayan anda dengan baik?', 'order' => 1005],
            ['start_time' => 2978.48, 'end_time' => 2981.34, 'target_text' => 'They did not treat Nabi Muhammad Sallallahu Alaihi Wasallam well.', 'source_text' => 'Dahulu mereka juga tidak melayan Nabi Muhammad Sallallahu Alaihi Wasallam dengan baik.', 'order' => 1006],
            ['start_time' => 2981.44, 'end_time' => 2982.46, 'target_text' => 'He took it as an honor.', 'source_text' => 'Namun Baginda menganggapnya sebagai suatu kemuliaan di sisi Allah.', 'order' => 1007],
            ['start_time' => 2982.56, 'end_time' => 2985.36, 'target_text' => 'He didn\'t compromise his faith.', 'source_text' => 'Baginda langsung tidak menggadaikan pegangan agamanya.', 'order' => 1008],
            ['start_time' => 2986.24, 'end_time' => 2987.62, 'target_text' => 'They tortured them in Mecca.', 'source_text' => 'Kaum musyrikin menyeksa para sahabat di kota Makkah.', 'order' => 1009],
            ['start_time' => 2987.72, 'end_time' => 2989.94, 'target_text' => 'They did not compromise their faith.', 'source_text' => 'Namun mereka tidak sesekali menggadaikan keimanan mereka.', 'order' => 1010],
            ['start_time' => 2990.04, 'end_time' => 2991.38, 'target_text' => 'So, they might not like you.', 'source_text' => 'Maka, mungkin ada orang yang tidak menyukai anda.', 'order' => 1011],
            ['start_time' => 2991.48, 'end_time' => 2992.22, 'target_text' => 'So what?', 'source_text' => 'Apakah masalahnya?', 'order' => 1012],
            ['start_time' => 2992.32, 'end_time' => 2993.34, 'target_text' => 'I\'m still going to pray.', 'source_text' => 'Saya tetap akan istiqamah mendirikan solat.', 'order' => 1013],
            ['start_time' => 2993.44, 'end_time' => 2999.58, 'target_text' => 'I\'m still my own I\'m unapologetically Muslim and I will prove to them that Islam is an amazing, beautiful religion.', 'source_text' => 'Saya tetap berpegang teguh pada prinsip saya — saya seorang Muslim tanpa sekelumit rasa malu dan saya akan buktikan kepada mereka bahawa Islam adalah agama yang amat indah dan mengagumkan.', 'order' => 1014],
            ['start_time' => 2999.68, 'end_time' => 3002.78, 'target_text' => 'We are taught to help Muslims, non-Muslims, whoever it may be.', 'source_text' => 'Kita dididik untuk membantu sesiapa sahaja — sama ada orang Islam mahupun bukan Islam, sesiapa jua yang memerlukan.', 'order' => 1015],
            ['start_time' => 3002.88, 'end_time' => 3006.54, 'target_text' => 'I gave you an example at the beginning of this talk of a dog.', 'source_text' => 'Saya telah memberikan contoh kepada anda pada awal ceramah tadi mengenai kisah seekor anjing.', 'order' => 1016],
            ['start_time' => 3006.64, 'end_time' => 3010.62, 'target_text' => 'And I told you even the animals we have to be kind to them, look out for them, and so on.', 'source_text' => 'Dan saya telah menegaskan bahawa terhadap haiwan sekalipun kita wajib berbuat ihsan, mengambil berat kebajikannya dan sebagainya.', 'order' => 1017],
            ['start_time' => 3010.72, 'end_time' => 3014.66, 'target_text' => 'I even said a pig you got to be kind to the pig.', 'source_text' => 'Malah saya turut menyebut terhadap babi sekalipun kita wajib berlaku ihsan dan tidak menyeksanya.', 'order' => 1018],
            ['start_time' => 3014.76, 'end_time' => 3016.9, 'target_text' => 'May Allah Almighty honor us all.', 'source_text' => 'Semoga Allah Yang Maha Berkuasa memuliakan kita semua.', 'order' => 1019],
            ['start_time' => 3017.0, 'end_time' => 3018.26, 'target_text' => 'May Allah Almighty bless us all.', 'source_text' => 'Semoga Allah Yang Maha Berkuasa melimpahkan barakah kepada kita semua.', 'order' => 1020],
            ['start_time' => 3018.36, 'end_time' => 3023.46, 'target_text' => 'So, this is how you start and this is how you get closer to Allah and this is how the doors begin to open.', 'source_text' => 'Maka begitulah cara anda bermula, dan begitulah cara untuk anda semakin mendekatkan diri kepada Allah, dan begitulah pintu-pintu rahmat mula terbuka luas.', 'order' => 1021],
            ['start_time' => 3023.56, 'end_time' => 3025.54, 'target_text' => 'Simple beginnings, simple start.', 'source_text' => 'Permulaan yang sederhana, langkah awal yang tulus.', 'order' => 1022],
            ['start_time' => 3025.64, 'end_time' => 3031.58, 'target_text' => 'We start with Allah subhanahu wa ta\'ala and Allah will open the doors one after the other and Allah will grant us the goodness', 'source_text' => 'Kita memulakannya kerana Allah subhanahu wa ta\'ala, nescaya Allah akan membuka pintu-pintu kebaikan satu demi satu dan mengurniakan kita kebaikan', 'order' => 1023],
            ['start_time' => 3031.68, 'end_time' => 3032.82, 'target_text' => 'of this world and the next.', 'source_text' => 'di dunia dan kebaikan di akhirat kelak.', 'order' => 1024],
            ['start_time' => 3032.92, 'end_time' => 3039.62, 'target_text' => 'So, we sought the forgiveness of Allah, we humbled ourselves, we started our prayer, and then Allah will open our doors.', 'source_text' => 'Maka kita telah memulakannya dengan istighfar memohon keampunan Allah, kita merendahkan diri dengan tawaduk, kita mendirikan solat lima waktu, dan sesudah itu Allah pasti membuka jalan kemudahan.', 'order' => 1025],
            ['start_time' => 3039.72, 'end_time' => 3042.42, 'target_text' => 'Don\'t justify when you\'ve done something wrong.', 'source_text' => 'Jangan sesekali mencari alasan membela diri apabila anda melakukan sesuatu kesilapan.', 'order' => 1026],
            ['start_time' => 3042.52, 'end_time' => 3048.34, 'target_text' => 'Always ask Allah, "Oh Allah, strengthen me to do that which is obligatory.', 'source_text' => 'Sentiasalah memohon kepada Allah, "Ya Allah, kurniakanlah aku kekuatan untuk menunaikan segala apa yang difardukan.', 'order' => 1027],
            ['start_time' => 3048.44, 'end_time' => 3051.86, 'target_text' => 'Oh Allah, strengthen me to do that which is pleasing to you.', 'source_text' => 'Ya Allah, berikanlah daku kekuatan untuk melakukan segala amalan yang mendatangkan keredaan-Mu.', 'order' => 1028],
            ['start_time' => 3051.96, 'end_time' => 3058.08, 'target_text' => 'And oh Allah, strengthen me to quit those things that are displeasing to you."', 'source_text' => 'Dan ya Allah, kurniakanlah daku keazaman untuk meninggalkan segala perkara yang mengundang kemurkaan-Mu."', 'order' => 1029],
            ['start_time' => 3058.72, 'end_time' => 3060.9, 'target_text' => 'May Allah Almighty bless you all.', 'source_text' => 'Semoga Allah Yang Maha Berkuasa memberkati anda semua.', 'order' => 1030],
            ['start_time' => 3061.0, 'end_time' => 3061.98, 'target_text' => 'These brothers have stood up.', 'source_text' => 'Saudara-saudara penganjur ini sudah mula berdiri.', 'order' => 1031],
            ['start_time' => 3062.08, 'end_time' => 3064.54, 'target_text' => 'They want me to leave Aberdeen.', 'source_text' => 'Nampaknya mereka memberi isyarat meminta saya meninggalkan Aberdeen.', 'order' => 1032],
            ['start_time' => 3064.64, 'end_time' => 3068.58, 'target_text' => 'I said something that seems to have offended some people.', 'source_text' => 'Mungkin ada kata-kata saya tadi yang menyinggung perasaan sesetengah orang?', 'order' => 1033],
            ['start_time' => 3068.68, 'end_time' => 3069.78, 'target_text' => 'Did I?', 'source_text' => 'Adakah saya menyinggung perasaan anda?', 'order' => 1034],
            ['start_time' => 3069.88, 'end_time' => 3070.7, 'target_text' => 'No, I didn\'t.', 'source_text' => 'Tidak, sama sekali tidak.', 'order' => 1035],
            ['start_time' => 3070.8, 'end_time' => 3071.26, 'target_text' => 'Come on, guys.', 'source_text' => 'Bertenanglah, sahabat-sahabat sekalian.', 'order' => 1036],
            ['start_time' => 3071.36, 'end_time' => 3071.76, 'target_text' => 'Masha Allah.', 'source_text' => 'Masya-Allah.', 'order' => 1037],
            ['start_time' => 3071.8, 'end_time' => 3073.14, 'target_text' => 'May Allah bless you all.', 'source_text' => 'Semoga Allah merahmati anda semua.', 'order' => 1038],
            ['start_time' => 3073.24, 'end_time' => 3074.02, 'target_text' => 'Masha Allah.', 'source_text' => 'Masya-Allah.', 'order' => 1039],
            ['start_time' => 3074.12, 'end_time' => 3075.66, 'target_text' => 'Can I ask you a question?', 'source_text' => 'Bolehkah saya bertanyakan satu soalan kepada anda?', 'order' => 1040],
            ['start_time' => 3075.76, 'end_time' => 3077.5, 'target_text' => 'What\'s your name?', 'source_text' => 'Siapakah nama anda?', 'order' => 1041],
            ['start_time' => 3077.6, 'end_time' => 3078.06, 'target_text' => 'Yunus.', 'source_text' => 'Yunus.', 'order' => 1042],
            ['start_time' => 3078.16, 'end_time' => 3079.14, 'target_text' => 'Masha Allah.', 'source_text' => 'Masya-Allah.', 'order' => 1043],
            ['start_time' => 3079.24, 'end_time' => 3082.0, 'target_text' => 'What made you come here today?', 'source_text' => 'Apakah yang mendorong anda hadir ke sini pada hari ini?', 'order' => 1044],
            ['start_time' => 3082.96, 'end_time' => 3084.82, 'target_text' => 'What was the reason?', 'source_text' => 'Apakah tujuannya?', 'order' => 1045],
            ['start_time' => 3084.92, 'end_time' => 3086.74, 'target_text' => 'Seems like you came a little bit early, right?', 'source_text' => 'Kelihatan seolah-olah anda hadir awal ke masjid ini, bukan?', 'order' => 1046],
            ['start_time' => 3086.84, 'end_time' => 3091.66, 'target_text' => 'Yeah, I wanted to be enlightened and I wanted to be enlightened, he says.', 'source_text' => '"Ya, saya ingin mendapatkan pencerahan ilmu," katanya.', 'order' => 1047],
            ['start_time' => 3091.76, 'end_time' => 3092.03, 'target_text' => 'And?', 'source_text' => 'Dan apa lagi?', 'order' => 1048],
            ['start_time' => 3092.08, 'end_time' => 3099.82, 'target_text' => 'something and I\'m about to start university and I wanted to Masha make sure that I live in accordance Alhamdulillah.', 'source_text' => '"Sesuatu nasihat kerana saya bakal memulakan pengajian di universiti dan saya ingin memastikan kehidupan saya sentiasa bertepatan dengan syariat," alhamdulillah.', 'order' => 1049],
            ['start_time' => 3099.92, 'end_time' => 3100.23, 'target_text' => 'Masha Allah.', 'source_text' => 'Masya-Allah.', 'order' => 1050],
            ['start_time' => 3100.28, 'end_time' => 3104.78, 'target_text' => 'The brother says he wanted to be enlightened and whatever else he said after that is connected to that.', 'source_text' => 'Saudara muda ini menyatakan bahawa dia hadir untuk menimba pencerahan ilmu dan apa jua yang disebutkannya selepas itu berkait rapat dengan niat murni tersebut.', 'order' => 1051],
            ['start_time' => 3104.88, 'end_time' => 3107.06, 'target_text' => 'Do feel you you feel a little bit better?', 'source_text' => 'Adakah anda kini berasa sedikit lebih tenang dan bersemangat?', 'order' => 1052],
            ['start_time' => 3107.16, 'end_time' => 3108.9, 'target_text' => 'Yes, I May Allah bless all of us.', 'source_text' => 'Ya. Semoga Allah melimpahkan barakah kepada kita semua.', 'order' => 1053],
            ['start_time' => 3109.0, 'end_time' => 3114.46, 'target_text' => 'The reason I ask you is many young people come and I always ask them what made you come and why did you come.', 'source_text' => 'Sebab utama saya bertanya adalah kerana ramai anak muda yang hadir dan saya sentiasa ingin tahu apa dorongan dan tujuan mereka hadir.', 'order' => 1054],
            ['start_time' => 3114.56, 'end_time' => 3117.66, 'target_text' => 'I hope it\'s never to take a photo with you.', 'source_text' => 'Saya berharap ia bukanlah semata-mata kerana ingin bergambar dengan saya.', 'order' => 1055],
            ['start_time' => 3117.76, 'end_time' => 3119.58, 'target_text' => 'Because that\'s not going to get you anywhere.', 'source_text' => 'Kerana gambar semata-mata tidak akan membawa anda ke mana-mana.', 'order' => 1056],
            ['start_time' => 3119.68, 'end_time' => 3121.9, 'target_text' => 'You get a photo, you don\'t get a photo.', 'source_text' => 'Sama ada anda dapat bergambar atau tidak dapat bergambar.', 'order' => 1057],
            ['start_time' => 3122.0, 'end_time' => 3124.84, 'target_text' => 'I I like to use the term', 'source_text' => 'Saya suka menggunakan istilah', 'order' => 1058],
            ['start_time' => 3125.08, 'end_time' => 3129.58, 'target_text' => 'which means in the eyes of Allah it\'s not even the weight of a fly.', 'source_text' => 'yang bermaksud di sisi Allah ia tidak bernilai walau seberat sayap lalat sekalipun.', 'order' => 1059],
            ['start_time' => 3129.68, 'end_time' => 3130.34, 'target_text' => 'That\'s what it is.', 'source_text' => 'Itulah hakikatnya.', 'order' => 1060],
            ['start_time' => 3130.44, 'end_time' => 3135.3, 'target_text' => 'So, inshallah if we can I don\'t mind a photo or two, but if you didn\'t get it don\'t be upset.', 'source_text' => 'Maka insya-Allah sekiranya berkesempatan, saya tidak keberatan untuk mengambil sekeping dua gambar, namun sekiranya anda tidak berpeluang mendapatkannya, janganlah berasa kecil hati.', 'order' => 1061],
            ['start_time' => 3135.4, 'end_time' => 3136.78, 'target_text' => 'We will walk out inshallah.', 'source_text' => 'Kami akan beredar keluar insya-Allah.', 'order' => 1062],
            ['start_time' => 3136.88, 'end_time' => 3141.26, 'target_text' => 'The young boys that are here that I see I\'m so touched to see so many young people.', 'source_text' => 'Anak-anak muda yang berada di sini yang saya perhatikan, hati saya amat tersentuh melihat begitu ramai golongan belia yang hadir.', 'order' => 1063],
            ['start_time' => 3141.36, 'end_time' => 3143.26, 'target_text' => 'How many of you are below the age of 30?', 'source_text' => 'Berapa ramai antara anda yang berumur di bawah 30 tahun?', 'order' => 1064],
            ['start_time' => 3143.36, 'end_time' => 3144.86, 'target_text' => 'Put up your hands.', 'source_text' => 'Sila angkat tangan anda.', 'order' => 1065],
            ['start_time' => 3144.96, 'end_time' => 3145.62, 'target_text' => 'Allahu Akbar.', 'source_text' => 'Allahu Akbar.', 'order' => 1066],
            ['start_time' => 3145.72, 'end_time' => 3146.9, 'target_text' => 'That\'s the bulk of the masjid.', 'source_text' => 'Hampir seluruh ruang masjid dipenuhi anak muda.', 'order' => 1067],
            ['start_time' => 3147.0, 'end_time' => 3148.18, 'target_text' => 'That\'s a very good sign.', 'source_text' => 'Itu adalah petanda yang amat memberangsangkan.', 'order' => 1068],
            ['start_time' => 3148.28, 'end_time' => 3153.66, 'target_text' => 'May Allah bless this wonderful community inshallah and may Allah subhanahu wa ta\'ala grant us ease and goodness.', 'source_text' => 'Semoga Allah melimpahkan barakah kepada komuniti yang hebat ini insya-Allah, dan semoga Allah subhanahu wa ta\'ala mengurniakan kemudahan dan kebaikan.', 'order' => 1069],
            ['start_time' => 3153.76, 'end_time' => 3159.54, 'target_text' => 'I don\'t want to get up, but these guys are trying to tell me you know what Masha Allah.', 'source_text' => 'Sebenarnya saya masih belum ingin beredar, namun sahabat-sahabat penganjur ini memberi isyarat mengingatkan saya, masya-Allah.', 'order' => 1070],
            ['start_time' => 3159.64, 'end_time' => 3160.46, 'target_text' => 'Masha Allah.', 'source_text' => 'Masya-Allah.', 'order' => 1071],
            ['start_time' => 3160.56, 'end_time' => 3161.42, 'target_text' => 'Just a minute.', 'source_text' => 'Beri saya masa seminit lagi.', 'order' => 1072],
            ['start_time' => 3161.52, 'end_time' => 3165.98, 'target_text' => 'So, I\'ve just been reminded that you know what I\'ve come here with Abdullah Aid.', 'source_text' => 'Saya baru sahaja diingatkan bahawa kehadiran saya ke sini adalah bersama-sama dengan pertubuhan kebajikan Abdullah Aid.', 'order' => 1073],
            ['start_time' => 3166.08, 'end_time' => 3173.38, 'target_text' => 'Abdullah Aid is a legitimate UK-based charity that I am not just affiliated to, I\'m an ambassador of.', 'source_text' => 'Abdullah Aid adalah sebuah badan kebajikan berdaftar yang sah di United Kingdom di mana saya bukan sekadar bernaung di bawahnya, malah saya merupakan dutanya.', 'order' => 1074],
            ['start_time' => 3173.48, 'end_time' => 3174.62, 'target_text' => 'I work with.', 'source_text' => 'Saya bekerjasama rapat dengan mereka.', 'order' => 1075],
            ['start_time' => 3174.72, 'end_time' => 3177.86, 'target_text' => 'You know, it\'s not easy to put your name next to a charity.', 'source_text' => 'Anda tahu, bukanlah mudah untuk meletakkan nama peribadi kita di samping sesebuah badan kebajikan.', 'order' => 1076],
            ['start_time' => 3177.96, 'end_time' => 3185.9, 'target_text' => 'I know so many charities, masha Allah they\'re doing good work, but the ones that I felt that I would like to work with fisabilillah', 'source_text' => 'Saya mengenali banyak pertubuhan kebajikan, masya-Allah mereka melakukan kerja-kerja yang baik, namun badan yang saya rasa terpanggil untuk bekerjasama fi sabilillah', 'order' => 1077],
            ['start_time' => 3186.0, 'end_time' => 3192.58, 'target_text' => 'because of the brothers being on a certain level I felt and I went through everything that I had to.', 'source_text' => 'disebabkan ketelusan dan integriti para penggeraknya, setelah saya meneliti secara terperinci segala operasinya.', 'order' => 1078],
            ['start_time' => 3192.68, 'end_time' => 3199.26, 'target_text' => 'These brothers, masha Allah I\'ve told them, you know what, once twice a year we will go around the country and we will introduce', 'source_text' => 'Sahabat-sahabat ini, masya-Allah saya telah berjanji dengan mereka bahawa sekali atau dua kali setahun kami akan menjelajah ke seluruh negara bagi memperkenalkan', 'order' => 1079],
            ['start_time' => 3199.36, 'end_time' => 3202.22, 'target_text' => 'Abdullah Aid and at the same time we will meet the communities.', 'source_text' => 'Abdullah Aid di samping mengeratkan ukhuwah bersama komuniti setempat.', 'order' => 1080],
            ['start_time' => 3202.32, 'end_time' => 3207.22, 'target_text' => 'So, I want you to reach out to be able to help us to help others.', 'source_text' => 'Oleh itu, saya menyeru anda semua untuk bersama-sama membantu kami agar kami dapat membantu mereka yang memerlukan.', 'order' => 1081],
            ['start_time' => 3207.32, 'end_time' => 3214.06, 'target_text' => 'We have a project, a work project, because so far something known as the gift aid, you might know what it is, right?', 'source_text' => 'Kami mempunyai sebuah projek wakaf, kerana setakat ini bantuan geran kerajaan seperti \'Gift Aid\' — anda mungkin tahu mengenainya, bukan?', 'order' => 1082],
            ['start_time' => 3214.16, 'end_time' => 3221.86, 'target_text' => 'Gift aid helps us to cover overheads, but the overheads are becoming more and we don\'t want to touch even a penny of the donation', 'source_text' => '\'Gift Aid\' membantu kami menampung kos operasi, namun kos operasi semakin meningkat dan kami sama sekali tidak mahu menyentuh walau satu sen pun daripada wang sumbangan', 'order' => 1083],
            ['start_time' => 3221.96, 'end_time' => 3222.78, 'target_text' => 'itself.', 'source_text' => 'derma orang ramai.', 'order' => 1084],
            ['start_time' => 3222.88, 'end_time' => 3229.14, 'target_text' => 'So, what we\'ve decided is we want a waqf to be able to bring in enough income to cover all the overheads.', 'source_text' => 'Maka, kami telah mengambil ketetapan untuk mewujudkan dana wakaf agar ia menjana pendapatan mampan bagi menampung keseluruhan kos operasi pentadbiran.', 'order' => 1085],
            ['start_time' => 3229.24, 'end_time' => 3236.5, 'target_text' => 'And whoever contributes to that waqf, which is not an easy project, they will have a reward of facilitation of everybody\'s', 'source_text' => 'Dan sesiapa yang menyumbang kepada dana wakaf tersebut — yang bukanlah suatu projek yang mudah — mereka akan beroleh ganjaran pahala mempermudahkan pengurusan', 'order' => 1086],
            ['start_time' => 3236.6, 'end_time' => 3238.9, 'target_text' => 'sadaqat and zakawat, inshallah.', 'source_text' => 'sedekah dan zakat setiap insan lain, insya-Allah.', 'order' => 1087],
            ['start_time' => 3239.0, 'end_time' => 3244.5, 'target_text' => 'So, tonight we\'re asking you, even if it means 10 pounds a month, you may donate towards the waqf, number one.', 'source_text' => 'Oleh itu, pada malam ini kami menyeru anda, sekalipun sekadar sumbangan 10 paun sebulan, anda boleh menyumbang ke arah dana wakaf ini, itu yang pertama.', 'order' => 1088],
            ['start_time' => 3244.6, 'end_time' => 3252.18, 'target_text' => 'Number two is you can still give zakat and sadaqat towards other projects across the globe, including Palestine and Gaza.', 'source_text' => 'Keduanya adalah anda masih boleh menyalurkan zakat dan sedekah anda untuk projek bantuan lain di seluruh dunia, termasuklah Palestin dan Gaza.', 'order' => 1089],
            ['start_time' => 3252.28, 'end_time' => 3258.78, 'target_text' => 'To the best of our ability, we will get whatever has to get to wherever it has to get to, inshallah, by the help of Allah', 'source_text' => 'Mengikut kemampuan terbaik kami, kami akan memastikan bantuan tersebut sampai ke destinasi yang disasarkan, insya-Allah, dengan pertolongan Allah', 'order' => 1090],
            ['start_time' => 3258.88, 'end_time' => 3259.7, 'target_text' => 'subhanahu wa ta\'ala.', 'source_text' => 'subhanahu wa ta\'ala.', 'order' => 1091],
            ['start_time' => 3259.8, 'end_time' => 3266.98, 'target_text' => 'So, that\'s just a word I decided to throw in so that I can remind you why we have come and what we have brought to you.', 'source_text' => 'Maka itulah sedikit pesanan yang ingin saya selitkan agar dapat mengingatkan anda tujuan utama kami hadir dan amanah yang kami bawa.', 'order' => 1092],
            ['start_time' => 3267.08, 'end_time' => 3268.14, 'target_text' => 'It\'s an opportunity.', 'source_text' => 'Ia adalah suatu peluang amal jariah.', 'order' => 1093],
            ['start_time' => 3268.24, 'end_time' => 3272.02, 'target_text' => 'Nonetheless, I know you are already doing a lot of good.', 'source_text' => 'Walau bagaimanapun, saya tahu anda semua sudah banyak menyumbang kebaikan.', 'order' => 1094],
            ['start_time' => 3272.12, 'end_time' => 3279.62, 'target_text' => 'So, inshallah, if there is a surplus, you can also donate to this wonderful, beautiful charity that we are connected to.', 'source_text' => 'Maka insya-Allah sekiranya ada lebihan rezeki, anda juga boleh menyumbang kepada badan kebajikan yang indah ini yang kami wakili.', 'order' => 1095],
            ['start_time' => 3279.72, 'end_time' => 3283.94, 'target_text' => 'Shukran to the Imam and the committee and all the brothers and sisters who are here.', 'source_text' => 'Jutaan terima kasih (syukran) kepada tuan Imam, jawatankuasa masjid dan seluruh saudara serta saudari yang hadir pada malam ini.', 'order' => 1096],
            ['start_time' => 3284.04, 'end_time' => 3287.1, 'target_text' => 'And inshallah, I pray that everything goes well.', 'source_text' => 'Dan insya-Allah, saya berdoa agar segala urusan dipermudahkan.', 'order' => 1097],
            ['start_time' => 3287.2, 'end_time' => 3290.1, 'target_text' => 'Aqulu qawli hadha wa sallallahu ala nabiyina Muhammad.', 'source_text' => 'Aqulu qawli hadha wa sallallahu \'ala nabiyyina Muhammad.', 'order' => 1098],
            ['start_time' => 3290.2, 'end_time' => 3292.44, 'target_text' => 'Wa salaam alaykum.', 'source_text' => 'Wa salaamu \'alaykum wa rahmatullah.', 'order' => 1099],
        ];

        $now = now();
        $rows = [];
        foreach ($subtitles as $sub) {
            $rows[] = [
                'id'          => (string) Str::uuid(),
                'video_id'    => $video->id,
